        .whereType<File>()
        .where((f) => f.path.endsWith('.html'))) {
      for (final m in _assetVersion.allMatches(file.readAsStringSync())) {
        versions.putIfAbsent(m.group(1)!, () => {}).add(m.group(2)!);
