// Pre-renders the agent-legible layer of fa1.dev (gh-1476):
//  - blog posts  -> site/blog/<slug>/index.html  (raw-HTML, BlogPosting JSON-LD)
//  - curated docs-> site/docs/<slug>/index.html  (TechArticle JSON-LD)
//  - blog index post list (generated block in site/blog/index.html)
//  - site/sitemap.xml  (real lastmod from committed front-matter/registry)
//  - site/llms-full.txt (llms.txt companion: full curated text, ≤150 KB)
//
// Usage:
//   dart run scripts/build_site.dart          # regenerate in place
//   dart run scripts/build_site.dart --check  # exit 1 if any artifact drifted
//
// Generated files are COMMITTED; CI (static gates) reruns the builder and
// fails on `git diff` — hand-editing generated output is a red build.

import 'dart:convert';
import 'dart:io';

const siteOrigin = 'https://fa1.dev';

/// A sitemap entry / generated page.
class SitePage {
  final String loc;      // absolute URL
  final String lastmod;  // YYYY-MM-DD, committed source of truth
  final String changefreq;
  final String priority;
}

/// Curated agent-quotable docs surfaced as static HTML (gh-1476 D5).
class DocsPage {
  final String slug;
  final String source;   // repo-relative docs/*.md
  final String updated;  // YYYY-MM-DD — bump when the source doc changes
}

const docsPages = [
  DocsPage('tool-availability', 'docs/tool-availability.md', '2026-10-10'),
  DocsPage('redaction', 'docs/redaction.md', '2026-10-10'),
  DocsPage('migrating-from-claude-copilot-codex', 'docs/migrating-from-claude-copilot-codex.md', '2026-10-10'),
  DocsPage('hep', 'docs/hep.md', '2026-10-10'),
