{"content":"// One-shot transform (gh-1476 D3): merges the three JSON-LD blocks in
// site/index.html into one validated @graph, adding Organization, WebSite,
// SoftwareSourceCode, and sameAs links. Run once; the result is committed.
import 'dart:convert';
import 'dart:io';

void main() {
  final file = File('site/index.html');
  final html = file.readAsStringSync();
  final blockRe = RegExp(
    r'<script type="application/ld\+json">\s*(\{.*?\})\s*</script>',
    dotAll: true,
  );
  final blocks = blockRe.allMatches(html).toList();
  if (blocks.length != 3) {
    stderr.writeln('expected 3 JSON-LD blocks, found ${blocks.length}');
    exit(1);
  }
  final nodes = <Map<String, dynamic>>[
    for (final b in blocks)
      (json.decode(b.group(1)!) as Map).cast<String, dynamic>(),
  ];
  Map<String, dynamic> byType(String type) =>
      nodes.firstWhere((n) => n['@type'] == type);

  final app = byType('SoftwareApplication');
  app['author'] = {'@id': 'https://fa1.dev/#org'};
  final sameAs = [repoUrl, pubDevUrl];
  // Rebuild with sameAs right after codeRepository, preserving key order.
  final rebuilt = <String, dynamic>{};
  app.forEach((k, v) {
    rebuilt[k] = v;
    if (k == 'codeRepository') rebuilt['sameAs'] = sameAs;
  });

  final graph = <Map<String, dynamic>>[
    {
      '@type': 'Organization',
      '@id': 'https://fa1.dev/#org',
      'name': 'IstiN',
      'url': 'https://github.com/IstiN',
      'sameAs': ['https://github.com/IstiN'],
    },
    {
      '@type': 'WebSite',
      '@id': 'https://fa1.dev/#website',
      'name': 'Fa — one agent harness, every device',
      'url': 'https://fa1.dev/',
      'publisher': {'@id': 'https://fa1.dev/#org'},
    },
    rebuilt,
    {
      '@type': 'SoftwareSourceCode',
      'name': 'flutter_agent_harness',
      'url': repoUrl,
      'codeRepository': repoUrl,
      'runtimePlatform': 'Dart',
      'programmingLanguage': 'Dart',
      'license': 'https://opensource.org/licenses/MIT',
      'author': {'@id': 'https://fa1.dev/#org'},
    },
    byType('FAQPage'),
    byType('HowTo'),
  ];

  final merged = {
    '@context': 'https://schema.org',
    '@graph': graph,
  };
  final newBlock =
      '<script type="application/ld+json">\n'
      '${const JsonEncoder.withIndent('  ').convert(merged)}\n'
      '</script>';

  final start = blocks.first.start;
  final end = blocks.last.end;
  file.writeAsStringSync(html.replaceRange(start, end, newBlock));
  stdout.writeln('merged ${graph.length} nodes into one @graph');
}

const repoUrl = 'https://github.com/IstiN/flutter_agent_harness';
const pubDevUrl = 'https://pub.dev/packages/flutter_agent_harness';
