const staticPages = [
  SitePage('$siteOrigin/', '2026-09-10', 'weekly', '1.0'),
  SitePage('$siteOrigin/app/', '2026-07-25', 'weekly', '0.9'),
  SitePage('$siteOrigin/app-store/', '2026-09-19', 'weekly', '0.8'),
  SitePage('$siteOrigin/blog/', '2026-09-20', 'weekly', '0.8'),
