{"content":"// One-shot transform (gh-1476 D3): merges the three JSON-LD blocks in
// site/index.html into one validated @graph, adding Organization, WebSite,
// SoftwareSourceCode, and sameAs links. Run once; the result is committed.
import 'dart:convert';
import 'dart:io';

void main() {
  final file = File('site/index.html');
  final html = file.readAsStringSync();
  final blockRe = RegExp(
    r'<script type="application/ld\+json">\s*(\{.*?\})\s*</script>',
    dotAll: true,
  );
  final blocks = blockRe.allMatches(html).toList();
  if (blocks.length != 3) {
    stderr.writeln('expected 3 JSON-LD blocks, found ${blocks.length}');
    exit(1);
  }
  final nodes = <Map<String, dynamic>>[
    for (final b in blocks)
      (json.decode(b.group(1)!) as Map).cast<String, dynamic>(),
  ];
  Map<String, dynamic> byType(String type) =>
      nodes.firstWhere((n) => n['@type'] == type);

  final app = byType('SoftwareApplication');
  app['author'] = {'@id': 'https://fa1.dev/#org'};
  final sameAs = [repoUrl, pubDevUrl];
  // Rebuild with sameAs right after codeRepository, preserving key order.
  final rebuilt = <String, dynamic>{};
  app.forEach((k, v) {
