const blogIndexFloor = '2026-09-20';

/// A loaded blog post (source: site/blog/posts/<slug>.md, kept in sync
/// with blog/posts/ by scripts/build_blog.dart).
class BlogPost {
  BlogPost({
    required this.slug,
    required this.meta,
    required this.body,
  });
  final String slug;
  final Map<String, String> meta;
  final String body;

  String get title => meta['title'] ?? slug;
