    for (final f in files)
      BlogPost(
        slug: f.uri.pathSegments.last.replaceAll('.md', ''),
        meta: parseFrontmatter(f.readAsStringSync()),
        body: stripFrontmatter(f.readAsStringSync()),
      ),
  ];
}

