<script>
fetch('posts.json')
  .then(r => r.json())
  .then(posts => {
    const root = document.getElementById('posts');
    if (!posts.length) { root.textContent = 'No posts yet.'; return; }
    root.innerHTML = '';
    for (const p of posts) {
      const a = document.createElement('a');
      a.className = 'post-card';
      a.href = 'post.html?p=' + encodeURIComponent(p.slug);
      a.innerHTML =
        (p.cover ? '<img src="posts/' + p.cover + '" alt="" loading="lazy">' : '') +
        '<h2></h2>' +
        '<div class="meta">' + esc(p.date) + (p.author ? ' · ' + esc(p.author) : '') + '</div>' +
        '<p></p>';
      a.querySelector('h2').textContent = p.title;
      a.querySelector('p').textContent = p.description;
      root.appendChild(a);
    }
  })
  .catch(() => { document.getElementById('posts').textContent = 'Failed to load posts.'; });

function esc(s) {
  return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
