  if (cover != null && start < bodyLines.length) {
    final img = RegExp(
      r'^!\[[^\]]*\]\(' + RegExp.escape(cover) + r'\)\s*$',
    ).firstMatch(bodyLines[start].trim());
    if (img != null) {
      coverFromBody = true;
      start++;
    }
  }
