  final desc = escapeHtml(p.description);
  final cover = p.cover;
  final video = p.video;
  final linkedin = p.linkedin;

  final bodyHtml = renderMarkdown(
    p.body,
    rewriteImg: (src) => RegExp(r'^(?:https?:)?//|^/|^data:').hasMatch(src)
        ? src
        : '../posts/$src',
  );","path":"scripts/build_site.dart"}

