        () async {
      final (_, body, _) = await get('/llms-full.txt');
      final postAndDocLocs = locs
          .where((l) => l.contains('/blog/20') || l.contains('/docs/'))
          .toList();
      expect(postAndDocLocs.length, greaterThanOrEqualTo(6));
      for (final loc in postAndDocLocs) {
